package com.fantamomo.mc.amongus.advancement.utils.step

import com.fantamomo.mc.amongus.advancement.AdvancementSequenceRunner
import com.fantamomo.mc.amongus.advancement.ExperimentalAdvancementApi

/**
 * Compile-time information about a single `step(...)` (or named `branch(...)`) call inside a runner.
 *
 * Instances are generated by the `advancement-compiler-plugin`, the runner is never executed for this.
 *
 * # Adding a new parameter
 *
 * Every constructor parameter (except [children], `groupId` and `groupRequiresAll`, which are filled by the plugin
 * itself) is filled with the argument of the `step(...)` parameter **with the same name**. To add a new piece of information:
 * 1. add the parameter to [step] and to the named `branch` functions (every function annotated with [StepDeclaration])
 * 2. add a constructor parameter with the same name (and a compatible type) here
 *
 * The plugin needs no changes. If the argument is omitted at the call site, the default value of the parameter here is used,
 * so every parameter that is optional in [step] must have a default here as well.
 * Arguments must be compile-time constants.
 *
 * @author Fantamomo
 * @since 2.5-SNAPSHOT
 */
@ExperimentalAdvancementApi
class StepInfo(
    val key: String,
    languageKey: String? = null,
    /** If true, this step and its children are not shown in the GUI. */
    val hidden: Boolean = false,
    /** If positive, the step must complete within this many seconds. */
    val timeoutSeconds: Int = 0,
    children: Array<StepInfo> = emptyArray(),
    /**
     * The id (unique per runner) of the `allOf`/`race` call this step is a direct branch of, `-1` if none.
     * Filled by the plugin.
     */
    val groupId: Int = -1,
    /** True if [groupId] belongs to an `allOf` (all branches needed), false for a `race`. Filled by the plugin. */
    val groupRequiresAll: Boolean = false,
) {
    /**
     * The language key that was explicitly passed to [step], `null` if the default should be used.
     *
     * @see languageKey
     */
    val declaredLanguageKey: String? = languageKey

    /** The steps that are lexically nested inside this step, in source order. */
    val children: List<StepInfo> = children.asList()

    /** The step this step is nested in, `null` for top-level steps. */
    var parent: StepInfo? = null
        private set

    /** The runner this step belongs to. */
    lateinit var runner: AdvancementSequenceRunner
        private set

    /** The index of this step among its siblings. */
    var index: Int = 0
        private set

    /**
     * The number shown in the GUI, e.g. `2` or `2a` for branches of a parallel group.
     * Hidden steps don't take a number.
     */
    var displayIndex: String = ""
        private set

    /** True if this is the first visible step of its parallel group. */
    var isFirstInGroup: Boolean = false
        private set

    /** The nesting depth of this step, `0` for top-level steps. */
    val depth: Int
        get() = parent?.let { it.depth + 1 } ?: 0

    /** True if this step is part of an `allOf` or `race`. */
    val isBranch: Boolean
        get() = groupId >= 0

    /** True if neither this step nor any of its parents is [hidden]. */
    val isVisible: Boolean
        get() = !hidden && (parent?.isVisible ?: true)

    /** The language key describing this step, either the [declared][declaredLanguageKey] one or the default. */
    val languageKey: String by lazy {
        declaredLanguageKey ?: defaultLanguageKey(runner.advancement.id, key)
    }

    /** This step and all nested steps in pre-order (parents before their children). */
    fun flatten(): Sequence<StepInfo> = sequence {
        yield(this@StepInfo)
        for (child in children) yieldAll(child.flatten())
    }

    internal fun bind(runner: AdvancementSequenceRunner, parent: StepInfo?, index: Int) {
        this.runner = runner
        this.parent = parent
        this.index = index
        for ([childIndex, child] in children.withIndex()) child.bind(runner, this, childIndex)
        assignDisplayIndices(children)
    }

    override fun toString() = "StepInfo(key=$key, children=$children)"

    companion object {
        fun defaultLanguageKey(advancementId: String, key: String) = "advancement.$advancementId.part.$key"

        /** Numbers the visible [siblings], consecutive branches of the same group share a number (`2a`, `2b`). */
        internal fun assignDisplayIndices(siblings: List<StepInfo>) {
            var number = 0
            var letter = 0
            var previousGroup = -1
            for (step in siblings) {
                if (step.hidden) continue
                if (step.isBranch && step.groupId == previousGroup) {
                    letter++
                } else {
                    number++
                    letter = 0
                }
                step.displayIndex = if (step.isBranch) "$number${'a' + letter}" else "$number"
                step.isFirstInGroup = step.isBranch && letter == 0
                previousGroup = step.groupId
            }
        }
    }
}
